-- X-UI v1 M2 (DATA_MODEL §3–§4): user preferences, institutions, accounts, account currencies,
-- cards, card ↔ account links, payment channels and channel sources. Generated by drizzle-kit,
-- then edited by hand (test/migrations-guard.test.ts and test/m2-schema.test.ts check the result
-- on libsql and on D1):
--   * expression index columns: drizzle-kit split ifnull("col", '') at the comma and quoted
--     each piece as a column name (SQLite: "no such column"); rewritten as ifnull(`col`, '').
--   * partial index WHERE clauses: "table"."col" written as `col`, as in DATA_MODEL.
--   * the hand-written triggers at the end (drizzle has no trigger API).
CREATE TABLE `account_card_links` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`card_id` text NOT NULL,
	`account_id` text NOT NULL,
	`currency` text,
	`role` text DEFAULT 'spending_source' NOT NULL,
	`is_default` integer DEFAULT false NOT NULL,
	`priority` integer,
	`status` text DEFAULT 'active' NOT NULL,
	`started_on` text,
	`ended_on` text,
	`notes` text,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`card_id`,`user_id`) REFERENCES `cards`(`id`,`user_id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`account_id`,`user_id`) REFERENCES `accounts`(`id`,`user_id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`account_id`,`user_id`,`currency`) REFERENCES `account_currencies`(`account_id`,`user_id`,`currency`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "account_card_links_role_ck" CHECK(role IN ('spending_source', 'top_up_source', 'other')),
	CONSTRAINT "account_card_links_is_default_ck" CHECK(is_default IN (0, 1)),
	CONSTRAINT "account_card_links_default_ck" CHECK(is_default = 0 OR (role = 'spending_source' AND status = 'active')),
	CONSTRAINT "account_card_links_priority_ck" CHECK(priority IS NULL OR priority >= 1),
	CONSTRAINT "account_card_links_status_ck" CHECK(status IN ('active', 'suspended', 'ended')),
	CONSTRAINT "account_card_links_ended_ck" CHECK(ended_on IS NULL OR status = 'ended')
);
--> statement-breakpoint
CREATE UNIQUE INDEX `account_card_links_open_uq` ON `account_card_links` (`card_id`,`account_id`,ifnull(`currency`, ''),`role`) WHERE `status` <> 'ended';--> statement-breakpoint
CREATE UNIQUE INDEX `account_card_links_default_uq` ON `account_card_links` (`card_id`,ifnull(`currency`, '')) WHERE `is_default` = 1;--> statement-breakpoint
CREATE INDEX `account_card_links_user_card_idx` ON `account_card_links` (`user_id`,`card_id`);--> statement-breakpoint
CREATE INDEX `account_card_links_user_account_idx` ON `account_card_links` (`user_id`,`account_id`);--> statement-breakpoint
CREATE TABLE `account_currencies` (
	`account_id` text NOT NULL,
	`user_id` text NOT NULL,
	`currency` text NOT NULL,
	`is_default` integer DEFAULT false NOT NULL,
	`status` text DEFAULT 'active' NOT NULL,
	`sort` integer DEFAULT 0 NOT NULL,
	`created_at` integer NOT NULL,
	PRIMARY KEY(`account_id`, `currency`),
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`account_id`,`user_id`) REFERENCES `accounts`(`id`,`user_id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "account_currencies_currency_ck" CHECK(currency GLOB '[A-Z][A-Z][A-Z]'),
	CONSTRAINT "account_currencies_is_default_ck" CHECK(is_default IN (0, 1)),
	CONSTRAINT "account_currencies_status_ck" CHECK(status IN ('active', 'closed')),
	CONSTRAINT "account_currencies_default_active_ck" CHECK(is_default = 0 OR status = 'active')
);
