-- A balance account must be e_money or stored_value (DATA_MODEL §3.6). A missing or other user's
-- account makes the subquery NULL, so the trigger stays quiet and the composite foreign key refuses it.
CREATE TRIGGER `payment_channels_balance_kind_insert` BEFORE INSERT ON `payment_channels`
FOR EACH ROW WHEN NEW.`balance_account_id` IS NOT NULL
  AND (SELECT `account_type` FROM `accounts` WHERE `id` = NEW.`balance_account_id` AND `user_id` = NEW.`user_id`) NOT IN ('e_money', 'stored_value')
BEGIN
  SELECT RAISE(ABORT, 'BALANCE_ACCOUNT_KIND: a payment channel balance account must be an e_money or stored_value account');
END;--> statement-breakpoint
CREATE TRIGGER `payment_channels_balance_kind_update` BEFORE UPDATE OF `balance_account_id`, `user_id` ON `payment_channels`
FOR EACH ROW WHEN NEW.`balance_account_id` IS NOT NULL
  AND (SELECT `account_type` FROM `accounts` WHERE `id` = NEW.`balance_account_id` AND `user_id` = NEW.`user_id`) NOT IN ('e_money', 'stored_value')
BEGIN
  SELECT RAISE(ABORT, 'BALANCE_ACCOUNT_KIND: a payment channel balance account must be an e_money or stored_value account');
END;--> statement-breakpoint
-- …and stays so: an account used as a balance account cannot change to another type.
CREATE TRIGGER `accounts_balance_kind_update` BEFORE UPDATE OF `account_type` ON `accounts`
FOR EACH ROW WHEN NEW.`account_type` NOT IN ('e_money', 'stored_value')
  AND EXISTS (SELECT 1 FROM `payment_channels` WHERE `balance_account_id` = NEW.`id`)
BEGIN
  SELECT RAISE(ABORT, 'BALANCE_ACCOUNT_KIND: a payment channel balance account must be an e_money or stored_value account');
END;--> statement-breakpoint
-- An account's institution is fixed once created (DATA_MODEL §3.2): a new contracting legal entity
-- means a new account. Setting the same value again is allowed; deletes (incl. user cascades) are
-- not updates and are unaffected.
CREATE TRIGGER `accounts_institution_immutable` BEFORE UPDATE OF `institution_id` ON `accounts`
FOR EACH ROW WHEN NEW.`institution_id` IS NOT OLD.`institution_id`
BEGIN
  SELECT RAISE(ABORT, 'ACCOUNT_INSTITUTION_IMMUTABLE: an account cannot move to another institution; create a new account');
END;